{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

(function () {
	'use strict';

	var STORAGE_KEY = 'todos-vanilla';
	var FILTER_KEY = 'todos-vanilla-filter';
	var ENTER_KEY = 13;
	var ESCAPE_KEY = 27;

	function loadTodos() {
		var raw = localStorage.getItem(STORAGE_KEY);
		if (!raw) return [];
		try {
			var parsed = JSON.parse(raw);
			return Array.isArray(parsed) ? parsed : [];
		} catch (e) {
			return [];
		}
	}

	function loadFilter() {
		var raw = localStorage.getItem(FILTER_KEY);
		if (raw === 'active' || raw === 'completed') return raw;
		return 'all';
	}

	function saveTodos(todos) {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function saveFilter(filter) {
		localStorage.setItem(FILTER_KEY, filter);
	}

	function nextId(todos) {
		var max = 0;
		for (var i = 0; i < todos.length; i++) {
			if (todos[i].id > max) max = todos[i].id;
		}
		return max + 1;
	}

	function applyFilter(hash) {
		if (hash === '#/active') return 'active';
		if (hash === '#/completed') return 'completed';
		return 'all';
	}

	function readHash() {
		var h = window.location.hash || '';
		return h;
	}

	/**
	 * @planks("the app is loaded with no todos")
	 * @planks("the app is loaded with the todos:")
	 * @planks("the app is loaded with {int} todo titled {string}")
	 * @planks("the app is loaded with {int} todos titled {string}")
	 * @planks("the user enters {string} into the new todo input and presses Enter")
	 * @planks("the todo list contains {string}")
	 * @planks("the todo list is empty")
	 * @planks("the todo list shows {string} and {string}")
	 * @planks("the todo list shows {string}, {string}, and {string} in that order")
	 * @planks("the todo list shows {string}, {string}, and {string}")
	 * @planks("the todo list shows {string}")
	 * @planks("the new todo input is empty")
	 * @planks("the new todo input has focus")
	 * @planks("the main section is hidden")
	 * @planks("the main section is visible")
	 * @planks("the footer is hidden")
	 * @planks("the footer is visible")
	 * @planks("the user marks {string} as complete")
	 * @planks("{string} has the completed state")
	 * @planks("{string} does not have the completed state")
	 * @planks("the user double-clicks the label of {string}")
	 * @planks("{string} is in editing mode")
	 * @planks("{string} is no longer in editing mode")
	 * @planks("the user changes the title to {string} and presses Enter")
	 * @planks("the user changes the title to {string} and presses Escape")
	 * @planks("the user clears the edit input and presses Enter")
	 * @planks("the user clicks the destroy button on {string}")
	 * @planks("{string} still appears in the list")
	 * @planks("{string} does not appear in the list")
	 * @planks("the user clicks the mark-all checkbox")
	 * @planks("every todo in the list has the completed state")
	 * @planks("no todo in the list has the completed state")
	 * @planks("the mark-all checkbox is checked")
	 * @planks("the mark-all checkbox is unchecked")
	 * @planks("one todo in the list has the completed state and the others do not")
	 * @planks("the active counter shows {string}")
	 * @planks("the active counter wraps the number 1 in a strong tag")
	 * @planks("the clear completed button is hidden")
	 * @planks("the clear completed button is visible")
	 * @planks("the user clicks the clear completed button")
	 * @planks("the user navigates to the active route")
	 * @planks("the user navigates to the completed route")
	 * @planks("the user is on the default route")
	 * @planks("the user is on the active route")
	 * @planks("the completed filter link has the selected class")
	 * @planks("the all filter link does not have the selected class")
	 * @planks("the active filter link does not have the selected class")
	 * @planks("the active filter link has the selected class")
	 * @planks("localStorage has a key named {string}")
	 * @planks("the stored entry at {string} exposes id, title, and completed fields")
	 * @planks("the stored entry at {string} has title {string} and completed false")
	 * @planks("the page reloads")
	 * @planks("{string} is not in editing mode")
	 */
	function app() {
		var document = window.document;
		var newTodoInput = document.querySelector('.new-todo');
		var mainSection = document.querySelector('.main');
		var footerSection = document.querySelector('.footer');
		var todoList = document.querySelector('.todo-list');
		var toggleAll = document.querySelector('.toggle-all');
		var counter = document.querySelector('.todo-count');
		var clearCompletedBtn = document.querySelector('.clear-completed');
		var filterLinks = document.querySelectorAll('.filters a');

		var state = {
			todos: loadTodos(),
			filter: loadFilter()
		};

		function persist() {
			saveTodos(state.todos);
		}

		function persistFilter() {
			saveFilter(state.filter);
		}

		function visibleTodos() {
			if (state.filter === 'active') return state.todos.filter(function (t) { return !t.completed; });
			if (state.filter === 'completed') return state.todos.filter(function (t) { return t.completed; });
			return state.todos;
		}

		function activeCount() {
			var n = 0;
			for (var i = 0; i < state.todos.length; i++) {
				if (!state.todos[i].completed) n++;
			}
			return n;
		}

		function completedCount() {
			var n = 0;
			for (var i = 0; i < state.todos.length; i++) {
				if (state.todos[i].completed) n++;
			}
			return n;
		}

		function renderMainVisibility() {
			if (state.todos.length === 0) {
				mainSection.classList.add('hidden');
				footerSection.classList.add('hidden');
			} else {
				mainSection.classList.remove('hidden');
				footerSection.classList.remove('hidden');
			}
		}

		function renderClearCompleted() {
			if (completedCount() === 0) {
				clearCompletedBtn.classList.add('hidden');
			} else {
				clearCompletedBtn.classList.remove('hidden');
			}
		}

		function renderToggleAll() {
			if (state.todos.length > 0 && activeCount() === 0) {
				toggleAll.checked = true;
			} else {
				toggleAll.checked = false;
			}
		}

		function renderCounter() {
			var n = activeCount();
			var word = n === 1 ? 'item' : 'items';
			counter.innerHTML = '<strong>' + n + '</strong> ' + word + ' left';
		}

		function renderFilters() {
			var hash = readHash();
			var current = applyFilter(hash);
			state.filter = current;
			persistFilter();
			for (var i = 0; i < filterLinks.length; i++) {
				var link = filterLinks[i];
				var href = link.getAttribute('href');
				if (
					(current === 'all' && (href === '#/' || href === '#!/')) ||
					(current === 'active' && href === '#/active') ||
					(current === 'completed' && href === '#/completed')
				) {
					link.classList.add('selected');
				} else {
					link.classList.remove('selected');
				}
			}
		}

		function renderList() {
			while (todoList.firstChild) todoList.removeChild(todoList.firstChild);
			var items = visibleTodos();
			for (var i = 0; i < items.length; i++) {
				var todo = items[i];
				var li = document.createElement('li');
				if (todo.completed) li.classList.add('completed');

				var view = document.createElement('div');
				view.className = 'view';

				var toggle = document.createElement('input');
				toggle.className = 'toggle';
				toggle.type = 'checkbox';
				toggle.checked = !!todo.completed;
				toggle.setAttribute('data-action', 'toggle');
				toggle.setAttribute('data-id', String(todo.id));

				var label = document.createElement('label');
				label.setAttribute('data-action', 'edit');
				label.setAttribute('data-id', String(todo.id));
				label.textContent = todo.title;

				var destroy = document.createElement('button');
				destroy.className = 'destroy';
				destroy.setAttribute('data-action', 'destroy');
				destroy.setAttribute('data-id', String(todo.id));

				view.appendChild(toggle);
				view.appendChild(label);
				view.appendChild(destroy);
				li.appendChild(view);

				var editInput = document.createElement('input');
				editInput.className = 'edit';
				editInput.value = todo.title;
				editInput.setAttribute('data-action', 'edit-input');
				editInput.setAttribute('data-id', String(todo.id));
				li.appendChild(editInput);

				todoList.appendChild(li);
			}
		}

		function render() {
			renderMainVisibility();
			renderClearCompleted();
			renderToggleAll();
			renderCounter();
			renderFilters();
			renderList();
		}

		function findTodoIndex(id) {
			for (var i = 0; i < state.todos.length; i++) {
				if (state.todos[i].id === id) return i;
			}
			return -1;
		}

		function addTodo(title) {
			var trimmed = title.trim();
			if (!trimmed) return;
			state.todos.push({
				id: nextId(state.todos),
				title: trimmed,
				completed: false
			});
			persist();
			render();
		}

		function toggleTodo(id) {
			var idx = findTodoIndex(id);
			if (idx === -1) return;
			state.todos[idx].completed = !state.todos[idx].completed;
			persist();
			render();
		}

		function setAllCompleted(completed) {
			for (var i = 0; i < state.todos.length; i++) {
				state.todos[i].completed = completed;
			}
			persist();
			render();
		}

		function clearCompleted() {
			state.todos = state.todos.filter(function (t) { return !t.completed; });
			persist();
			render();
		}

		function startEdit(id) {
			var li = todoList.querySelector('li .edit[data-id="' + id + '"]');
			if (!li) return;
			var liEl = li.parentNode;
			liEl.classList.add('editing');
			li.focus();
			li.setSelectionRange(li.value.length, li.value.length);
		}

		function finishEdit(id, newTitle, save) {
			var li = todoList.querySelector('li:has(.edit[data-id="' + id + '"])');
			if (!li) li = todoList.querySelectorAll('.todo-list li')[findTodoIndex(id)];
			var idx = findTodoIndex(id);
			if (idx === -1) return;
			var todo = state.todos[idx];
			if (save) {
				var trimmed = newTitle.trim();
				if (!trimmed) {
					state.todos.splice(idx, 1);
				} else {
					todo.title = trimmed;
				}
			}
			persist();
			render();
		}

		function cancelEdit(id) {
			var idx = findTodoIndex(id);
			if (idx === -1) return;
			render();
		}

		function destroyTodo(id) {
			var idx = findTodoIndex(id);
			if (idx === -1) return;
			state.todos.splice(idx, 1);
			persist();
			render();
		}

		newTodoInput.addEventListener('keydown', function (e) {
			if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
				var title = newTodoInput.value;
				if (title.trim()) {
					addTodo(title);
					newTodoInput.value = '';
				} else {
					newTodoInput.value = '';
				}
			}
		});

		todoList.addEventListener('click', function (e) {
			var target = e.target;
			var action = target.getAttribute('data-action');
			if (!action) return;
			var id = parseInt(target.getAttribute('data-id'), 10);
			if (action === 'destroy') destroyTodo(id);
		});

		todoList.addEventListener('change', function (e) {
			var target = e.target;
			var action = target.getAttribute('data-action');
			if (action === 'toggle') {
				var id = parseInt(target.getAttribute('data-id'), 10);
				toggleTodo(id);
			}
		});

		todoList.addEventListener('dblclick', function (e) {
			var target = e.target;
			var action = target.getAttribute('data-action');
			if (action === 'edit') {
				var id = parseInt(target.getAttribute('data-id'), 10);
				startEdit(id);
			}
		});

		todoList.addEventListener('keydown', function (e) {
			var target = e.target;
			if (!target.classList.contains('edit')) return;
			var id = parseInt(target.getAttribute('data-id'), 10);
			if (e.keyCode === ENTER_KEY || e.key === 'Enter') {
				finishEdit(id, target.value, true);
			} else if (e.keyCode === ESCAPE_KEY || e.key === 'Escape') {
				cancelEdit(id);
			}
		});

		todoList.addEventListener('blur', function (e) {
			var target = e.target;
			if (!target.classList.contains('edit')) return;
			var id = parseInt(target.getAttribute('data-id'), 10);
			if (target.closest('li.editing')) {
				finishEdit(id, target.value, true);
			}
		}, true);

		toggleAll.addEventListener('change', function () {
			if (state.todos.length === 0) return;
			setAllCompleted(toggleAll.checked);
		});

		clearCompletedBtn.addEventListener('click', function () {
			clearCompleted();
		});

		window.addEventListener('hashchange', function () {
			renderFilters();
			renderList();
		});

		newTodoInput.focus();

		render();
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', app);
	} else {
		app();
	}
})();

const { setWorldConstructor, BeforeStep } = require('@cucumber/cucumber');
const fs = require('fs');
const path = require('path');
const { Window } = require('happy-dom');

const HTML_PATH = path.resolve(__dirname, '..', '..', 'index.html');
const APP_JS_PATH = path.resolve(__dirname, '..', '..', 'js', 'app.js');

function loadWorld(preload, hash) {
	const window = new Window();
	const document = window.document;

	if (preload) {
		for (const key of Object.keys(preload)) {
			window.localStorage.setItem(key, preload[key]);
		}
	}

	if (hash) {
		window.location.hash = hash;
	}

	const html = fs.readFileSync(HTML_PATH, 'utf-8');
	document.write(html);

	const appJs = fs.readFileSync(APP_JS_PATH, 'utf-8');
	window.eval(appJs);

	return window;
}

class TodoWorld {
	constructor() {
		this.window = null;
		this.document = null;
	}

	get doc() {
		if (!this.window) this.window = loadWorld();
		if (!this.document) this.document = this.window.document;
		return this.document;
	}

	get win() {
		if (!this.window) this.window = loadWorld();
		return this.window;
	}

	reload() {
		this.window = loadWorld();
		this.document = this.window.document;
	}

	reset() {
		this.window = loadWorld();
		this.document = this.window.document;
	}

	loadWithTodos(todos) {
		const preload = { 'todos-vanilla': JSON.stringify(todos) };
		this.window = loadWorld(preload);
		this.document = this.window.document;
	}

	reloadWithStorage() {
		const storedTodos = this.win.localStorage.getItem('todos-vanilla');
		const storedFilter = this.win.localStorage.getItem('todos-vanilla-filter');
		const preload = {};
		if (storedTodos !== null) preload['todos-vanilla'] = storedTodos;
		if (storedFilter !== null) preload['todos-vanilla-filter'] = storedFilter;
		const hash = storedFilter === 'active' ? '#/active'
			: storedFilter === 'completed' ? '#/completed'
			: '#/';
		this.window = loadWorld(preload, hash);
		this.document = this.window.document;
	}

	setHash(hash) {
		this.win.location.hash = hash;
		this.win.dispatchEvent(new this.win.HashChangeEvent('hashchange'));
	}

	focusInput(selector) {
		const el = this.doc.querySelector(selector);
		if (el) el.focus();
		return el;
	}

	click(selector) {
		const el = this.doc.querySelector(selector);
		if (!el) throw new Error('No element matching ' + selector);
		const ev = new this.win.MouseEvent('click', { bubbles: true, cancelable: true });
		el.dispatchEvent(ev);
		return el;
	}

	dblclick(selector) {
		const el = this.doc.querySelector(selector);
		if (!el) throw new Error('No element matching ' + selector);
		const ev = new this.win.MouseEvent('dblclick', { bubbles: true, cancelable: true });
		el.dispatchEvent(ev);
		return el;
	}

	check(selector, checked) {
		const el = this.doc.querySelector(selector);
		if (!el) throw new Error('No element matching ' + selector);
		el.checked = checked;
		const ev = new this.win.Event('change', { bubbles: true });
		el.dispatchEvent(ev);
		return el;
	}

	type(selector, value) {
		const el = this.doc.querySelector(selector);
		if (!el) throw new Error('No element matching ' + selector);
		el.value = value;
		return el;
	}

	press(selector, key) {
		const el = this.doc.querySelector(selector);
		if (!el) throw new Error('No element matching ' + selector);
		const keyName = key === 'Enter' ? 'Enter' : key === 'Escape' ? 'Escape' : key;
		const ev = new this.win.KeyboardEvent('keydown', { key: keyName, keyCode: key === 'Enter' ? 13 : (key === 'Escape' ? 27 : 0), bubbles: true, cancelable: true });
		el.dispatchEvent(ev);
		return el;
	}

	isVisible(el) {
		if (!el) return false;
		if (el.classList && el.classList.contains('hidden')) return false;
		const style = this.win.getComputedStyle(el);
		return style.display !== 'none';
	}

	isHidden(el) {
		return !this.isVisible(el);
	}

	todoItems() {
		return Array.from(this.doc.querySelectorAll('.todo-list li'));
	}

	findTodoByTitle(title) {
		const items = this.todoItems();
		return items.find(function (li) {
			const label = li.querySelector('label');
			return label && label.textContent === title;
		});
	}

	existsByTitle(title) {
		return !!this.findTodoByTitle(title);
	}

	todoTitles() {
		return this.todoItems().map(function (li) {
			const label = li.querySelector('label');
			return label ? label.textContent : '';
		});
	}

	todosAllCompleted() {
		const items = this.todoItems();
		if (items.length === 0) return false;
		return items.every(function (li) { return li.classList.contains('completed'); });
	}

	todosAnyIncomplete() {
		const items = this.todoItems();
		return items.some(function (li) { return !li.classList.contains('completed'); });
	}

	parseJson(raw) {
		try {
			return JSON.parse(raw);
		} catch (e) {
			return null;
		}
	}
}

BeforeStep(function (arg) {
	const stepAstNodeId = arg.pickleStep.astNodeIds[0];
	const feature = arg.gherkinDocument.feature;
	for (const child of feature.children) {
		if (child.scenario) {
			for (const step of child.scenario.steps) {
				if (step.id === stepAstNodeId) {
					this.currentStepKeyword = step.keyword;
					return;
				}
			}
		}
		if (child.rule) {
			for (const ruleChild of child.rule.children) {
				for (const step of ruleChild.scenario.steps) {
					if (step.id === stepAstNodeId) {
						this.currentStepKeyword = step.keyword;
						return;
					}
				}
			}
		}
	}
	this.currentStepKeyword = 'Then';
});

setWorldConstructor(TodoWorld);

const { When } = require('@cucumber/cucumber');

When('the user enters {string} into the new todo input and presses Enter', function (value) {
	const input = this.doc.querySelector('.new-todo');
	input.value = value;
	const ev = new this.win.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true, cancelable: true });
	input.dispatchEvent(ev);
});

When('the user double-clicks the label of {string}', function (title) {
	const items = this.todoItems();
	const li = items.find(li => li.querySelector('label')?.textContent === title);
	const label = li.querySelector('label');
	const ev = new this.win.MouseEvent('dblclick', { bubbles: true, cancelable: true });
	label.dispatchEvent(ev);
});

When('the user changes the title to {string} and presses Enter', function (newTitle) {
	const editingLi = this.doc.querySelector('.todo-list li.editing');
	const input = editingLi.querySelector('.edit');
	input.value = newTitle;
	const ev = new this.win.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true, cancelable: true });
	input.dispatchEvent(ev);
});

When('the user changes the title to {string} and presses Escape', function (newTitle) {
	const editingLi = this.doc.querySelector('.todo-list li.editing');
	const input = editingLi.querySelector('.edit');
	input.value = newTitle;
	const ev = new this.win.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true, cancelable: true });
	input.dispatchEvent(ev);
});

When('the user clears the edit input and presses Enter', function () {
	const editingLi = this.doc.querySelector('.todo-list li.editing');
	const input = editingLi.querySelector('.edit');
	input.value = '';
	const ev = new this.win.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true, cancelable: true });
	input.dispatchEvent(ev);
});

When('the user clicks the clear completed button', function () {
	const btn = this.doc.querySelector('.clear-completed');
	const ev = new this.win.MouseEvent('click', { bubbles: true, cancelable: true });
	btn.dispatchEvent(ev);
});

When('the user clicks the destroy button on {string}', function (title) {
	const items = this.todoItems();
	const li = items.find(li => li.querySelector('label')?.textContent === title);
	const btn = li.querySelector('.destroy');
	const ev = new this.win.MouseEvent('click', { bubbles: true, cancelable: true });
	btn.dispatchEvent(ev);
});

When('the user clicks the mark-all checkbox', function () {
	const checkbox = this.doc.querySelector('.toggle-all');
	const newState = !checkbox.checked;
	checkbox.checked = newState;
	const ev = new this.win.Event('change', { bubbles: true });
	checkbox.dispatchEvent(ev);
});

When('the user navigates to the active route', function () {
	this.setHash('#/active');
});

When('the user navigates to the completed route', function () {
	this.setHash('#/completed');
});

When('the page reloads', function () {
	this.reloadWithStorage();
});

const { Then } = require('@cucumber/cucumber');
const assert = require('assert');

Then('the main section is hidden', function () {
	const main = this.doc.querySelector('.main');
	assert.ok(this.isHidden(main), 'main section should be hidden');
});

Then('the main section is visible', function () {
	const main = this.doc.querySelector('.main');
	assert.ok(this.isVisible(main), 'main section should be visible');
});

Then('the footer is hidden', function () {
	const footer = this.doc.querySelector('.footer');
	assert.ok(this.isHidden(footer), 'footer should be hidden');
});

Then('the footer is visible', function () {
	const footer = this.doc.querySelector('.footer');
	assert.ok(this.isVisible(footer), 'footer should be visible');
});

Then('the todo list contains {string}', function (title) {
	assert.ok(this.existsByTitle(title), 'todo list should contain ' + title);
});

Then('the todo list is empty', function () {
	assert.strictEqual(this.todoItems().length, 0);
});

Then('the todo list shows {string} and {string}', function (a, b) {
