const fs = require('fs');
const path = require('path');
const { Window } = require('happy-dom');

const HTML_PATH = path.resolve(__dirname, '..', '..', 'index.html');
const APP_JS_PATH = path.resolve(__dirname, '..', '..', 'js', 'app.js');

function loadWorld(preload, hash) {
	const window = new Window();
	const document = window.document;

	if (preload) {
		for (const key of Object.keys(preload)) {
			window.localStorage.setItem(key, preload[key]);
		}
	}

	if (hash) {
		window.location.hash = hash;
	}

	const html = fs.readFileSync(HTML_PATH, 'utf-8');
	document.write(html);

	const appJs = fs.readFileSync(APP_JS_PATH, 'utf-8');
	window.eval(appJs);

	return window;
}

class TodoWorld {
	constructor() {
		this.window = null;
		this.document = null;
